SourceCode.Declaration:
/// <summary>
/// Parameter data contract for importing files from an SFTP server
/// </summary>
[DataContract]
class OMGInboundDataContract_SFTP extends OMGInboundDataContract_Azure
{
    OMGSftpHostName             hostName;
    OMGSftpPort                 port = 22;
    OMGSftpUserName             userName;
    OMGSftpSourceDirectory      sourceDirectory;
    OMGSftpArchiveDirectory     archiveDirectory;

}

Method.Source:
[DataMember, OMGSftpHostNameAttribute, SysOperationDisplayOrder('3')]
public OMGSftpHostName parmHostName(OMGSftpHostName _hostName = hostName)
{
    hostName = _hostName;
    return hostName;
}

[DataMember, OMGSftpPortAttribute, SysOperationDisplayOrder('4')]
public OMGSftpPort parmPort(OMGSftpPort _port = port)
{
    port = _port;
    return port;
}

[DataMember, OMGSftpUserNameAttribute, SysOperationDisplayOrder('5')]
public OMGSftpUserName parmUserName(OMGSftpUserName _userName = userName)
{
    userName = _userName;
    return userName;
}

[DataMember, OMGSftpDirectoryAttribute, SysOperationDisplayOrder('10')]
public OMGSftpSourceDirectory parmSourceDirectory(OMGSftpSourceDirectory _sourceDirectory = sourceDirectory)
{
    sourceDirectory = _sourceDirectory;
    return sourceDirectory;
}

[DataMember, OMGSftpDirectoryAttribute, OMGArchiveDirectory, SysOperationDisplayOrder('11')]
public OMGSftpArchiveDirectory parmArchiveDirectory(OMGSftpArchiveDirectory _archiveDirectory = archiveDirectory)
{
    archiveDirectory = _archiveDirectory;
    return archiveDirectory;
}

/// <summary>
/// The caption used on the dialog
/// </summary>
/// <returns>A descriptive text</returns>
public Description dialogCaption()
{
    return "@OMG:ImportFromSftp";
}
